def bf(planet1, planet2):
    # Check if both planet names are valid
    if planet1 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    if planet2 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    # Initialize a deque with the planets' orbits
    orbits = deque(sorted(["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]))

    # Process each pair of planets from closest to farthest
    while orbits:
        p1 = orbits.popleft()
        p2 = orbits.pop()

        # If either planet is invalid, break out of loop
        if p1 == "" or p2 == "":
            break

        # Add the remaining planets to the deque
        for i in range(len(orbits)):
            if orbits[i] != p1 and orbits[i] != p2:
                orbits.append(orbits[i])

    # Return the result as a tuple
    return tuple(orbits)

